    "resumen": "La presente investigación “Aplicación del mantenimiento preventivo para mejorar la disponibilidad de equipos de carguío y acarreo en la Empresa Cordeje SAC” tuvo como objetivo Aplicar el mantenimiento preventivo para mejorar la disponibilidad de los equipos de carguío y acarreo en la Empresa Cordeje S.A.C. en la compañía minera SUMMA GOLD CORPORATION. Cuya muestra estuvo constituida por 20 equipos de acarreo y 2 de carguío. Utilizando como instrumentos el programa de mantenimiento preventivo, las ordenes de trabajo y la ficha de registro. En los resultados se determinó que, tras la aplicación del mantenimiento preventivo, se mejoró el tiempo promedio entre fallas de los equipos de carguío y acarreo durante el periodo enero a junio del 2024, como también los tiempos promedio de reparación de los equipos. Concluyendo que, a través del uso del mantenimiento preventivo, se incrementó la disponibilidad promedio de los equipos de acarreo de 77.45% a 86.91% y la disponibilidad promedio de los equipos de carguío de 77.45% a 87.14%, reduciendo la cantidad de fallas y tiempos de inactividad, mejorando la productividad de la empresa Cordeje S.A.C.",
