    "area": "Logística y Cadena de Suministro",
    "resumen": "El siguiente informe de suficiencia laboral tiene como objetivo general implementar la gestión de compras para mejorar la atención de los requerimientos de la Red de Salud Cajabamba. De acuerdo al análisis realizado los problemas identificados fueron el incumplimiento de la programación de las contrataciones, reformulación de los requerimientos, cotizaciones con precios sobre valorados en las indagaciones de mercado, demora en la cotización de los proveedores, deficiencias en la indagación de mercado, la no utilización del uso de otras fuentes distintas a las cotizaciones durante la indagación de mercado. el riesgo de no contar con pluralidad de postores y el riesgo de declararse desiertos o nulos los procedimientos de selección. Se implemento la gestión de compras principalmente en plan de capacitación. Como conclusión principal de acuerdo con el objetivo general después de la implementación de la gestión de compras en la red de salud Cajabamba la atención en los requerimientos paso de 81.76% en el año 2023 a 94.08% en lo que va del año 2024, teniendo un aumento del 12.32%.",
