    "anio": 2023,
    "area": "Logística y Cadena de Suministro",
    "resumen": "This report entitled \"Process of reception, storage and distribution of sugar in its different presentations of a Distribution Center\" aims to publicize the work experience acquired in the company Casa Grande S.A.A. The experience acquired is oriented to the area of finished product warehouses, serving as Head of Distribution Centers, where my main function is to control the finished product distribution centers that the company has, supervising the processes of reception, storage and dispatch of the finished product. The document consists of three chapters, the first of which describes Casa Grande S.A.A, the scope of its operations, its history, mission and vision. The second chapter describes in a summarized technical aspects of logistics, warehouses, inventories, which are important to know to perform the position of Head of Distribution Centers. The third chapter describes the functions performed as Head of Distribution Centers, their scope, and the processes of reception, storage and dispatch of sugar.",
