    "asesor": "Rodríguez Novoa, Francisco Elías",
    "anio": 2023,
    "area": "Gestión de la Calidad",
    "resumen": "The general objective of this research is to improve the quality of the secondary distribution service of drinking water in the operation and maintenance team of the San Juan de Lurigancho (EOMR-SJL) - Sedapal networks with the proposal of implementation of a quality management system (QMS) based on the ISO 9001: 2015 standard. In the initial diagnosis of Sedapal's \"secondary distribution of drinking water\" process, it was found that user satisfaction with respect to the quality of the water received was 59.6% in 2018. In addition, in the same year the capacity was evaluated. of the process and it turned out that it was not potentially capable of meeting the accepted specifications of the service. Subsequently, it was verified that compliance with the requirements of ISO 9001: 2015 in the EOMR-SJL reached 14.80%. That is why the documented information and the quality management system implementation plan were designed based on the requirements of the standard for its implementation and maintenance. By applying the QMS, the process will be better planned, organized and standardized, therefore, there will be better control of the parameters that regulate the distribution of water and",
