    "area": "Seguridad y Salud Ocupacional",
    "resumen": "The objective of this research was to implement strategies in the occupational health and safety system to reduce the accident rate of the El Brocal Project, in the San Martín Contratistas Generales S.A. Company, this leads to a decrease in the occurrence of events and that the worker can correctly identify the dangers and risks of their routine activities. Through the initial diagnosis made and the analysis of statistics of the events that occurred, the strategy implementation methodology was used, which involved the management of the work through the accompaniment and commitment to the development of activities to strengthen relations with the force. labor; in the selection and training of the operators, it allowed having workers with an adequate profile and trained in the development of their activities to face the adverse conditions due to the climatic factor; With the reinforcement of effective supervision towards the command line, it was possible for the employed personnel to feel identified by the company. Due to the constant failures of the vehicles and mobile equipment, the preventive maintenance program was implemented in order to have maximum mechanical availability; A c",
