    "resumen": "La presente Investigación que se realizó en la Curtiembre Santa Rosa S.A.C. ubicada en el distrito de la esperanza, ciudad de Trujillo. Se dedica a la producción del curtido de cuero de ganado ovino y vacuno. Tiene como propósito determinar las malas posturas de los trabajadores que en una larga jornada laboral acarrea la aparición de sintomatologías de trastornos músculos esqueléticos (TME) durante la etapa de trabajo y la actividad que desempeña. La propuesta planteada busca mejorar las condiciones de trabajo del operario, es decir brindarle una mayor seguridad y satisfacción. Cuando desarrollaban sus labores y el avance de sus actividades, aumenta la posibilidad de causar que los trabajadores presenten dolencias en algunas partes de su cuerpo. El objetivo principal es evaluar las actividades e intervenir ergonómicamente a los trabajadores para minimizar los riesgos ergonómicos que puedan existir en el desarrollo de las tareas establecidas por una actividad. Para el desarrollo de esta investigación se empleó la Norma Básica de ergonomía y de procedimiento de evaluación de riesgo disergonomico (RM. 375-2008-TR). La actual tesis consistió en realizar un análisis ergonómico (método ",
