    "resumen": "ABSTRACT In this research work was carried out the implementation of a design and development process (D & D) for the Quality Management System (QMS) under ISO 9001: 2015 number 8.3 of design and development applied to continuous training programs, with the objective of fulfilling the strategic objective, quality objective, scope, planning and control, audits, validation and verification of the design and development process, in the company GICA Ingenieros. The research was carried out under the philosophy of continuous improvement, process-based management, the Deming cycle (Plan-Do-Check-Act;) and compliance with the requirements of ISO 9001: 2015 number 8.3 of design and development applied to continuous training programs, for this the methodology of implementation of the design and development process of GICA Ingenieros was used. This methodology has levels aligned to Annex SL (context of the organization, leadership, planning, support, operation, performance measurement and improvement) being grouped into 05 levels called: Initial Organizational Context, Planning, Operation, Control and Final Organizational Context. The development of 05 levels is divided into 17 phases, in or",
