    "anio": 2018,
    "area": "Gestión de la Calidad",
    "resumen": "La industria alimentaria está experimentando una mayor exigencia en cuanto a la inocuidad, por lo cual se viene usando diferentes sistemas que guíen los procesos y que permitan obtener una mejor eficiencia. El sistema HACCP proporciona herramientas que ayudan a establecer indicadores de cumplimiento, los cuales mejoran la producción, a través de la identificación y determinación de puntos críticos, cuales a su vez serán controlados por medio de límites críticos. Es necesario que estos sean evaluados, de tal manera que se pueda establecer acciones preventivas y correctivas necesarias que generen mejoras. Se realizó un diagnóstico inicial usando la Norma sanitaria para la aplicación del sistema HACCP en la fabricación de alimentos y bebidas RM N° 449-2006 / MINSA y se identificó la situación actual del laboratorio de Cereales y Leguminosas, permitiendo así determinar el plan de acción que ayude a mejorar las condiciones de inocuidad en los alimentos. Obteniéndose un 72% de cumplimiento post implementación de BPM, POES y HACCP, a comparación de un 63% de no cumplimento inicial. Se elaboraron una serie de indicadores con los cuales se podrán medir y hacer seguimiento al cumplimiento de",
