    "anio": 2018,
    "area": "Seguridad y Salud Ocupacional",
    "resumen": "ABSTRACT The machining, welding and cutting processes were investigated in order to reduce their accidents. A Health and Safety at Work Management System was proposed for these processes that integrates standards, international standards (OHSAS 18001, OHSAS 18002, ANSI B11, AWS / ANSI Z49.1) and national regulations (Ley 29783 and others from various sectors ), in force in matters of health and safety at work. The methods and techniques used to analyze the information obtained were Cause - Effect analysis, SWOT analysis, statistical analysis of the information sent by MTPE and others recommended by international standards and Peruvian standards on HSE (baseline matrix, matrix IPERC, protocol for inspection of research in metalworking activities, among others). The current situation was diagnosed and identified priorities, problems and/or needs, as well as the administrative, operational and technological improvements in occupational health and safety of machining, welding and cutting processes. A protection system was proposed for machine tools, portable machinery, machines and equipment for welding and cutting from electronic devices, recommended by ANSI B11. It also included good",
