    "area": "Seguridad y Salud Ocupacional",
    "resumen": "Occupational Health and Safety has the purpose of creating the conditions for the worker to carry out their work efficiently and without risks, avoiding events and damages that may affect their health and integrity, the entity's assets and the environment, and thus promoting the raising of the quality of life of the worker, his family and social stability. The present research work based on the \"DESIGN OF AN OCCUPATIONAL HEALTH AND SAFETY PLAN ACCORDING TO LAW 29783, ITS REGULATIONS D.S. 005 - 2012 - TR AND ITS MODIFICATORIES AT THE COMPANY FORTALEZA SRL IN THE CITY OF TALARA, 2016 \"; Its main objective is to minimize the dangers and risks to which employees are exposed every day. The company has as main services are industrial assembly, industrial paints, heavy machinery rental and construction and repair of civil works. For the study, methods of data collection have been used through surveys, interviews and field visits to subsequently record it in the IPERC matrix, where it is verified which are the most critical hazards and risks and finally find the optimal control measures. The diagnosis of the current situation of the company was made, with the purpose of verifying the perce",
