    "area": "Gestión de la Calidad",
    "resumen": "The present work elaborates the \"PROPOSAL OF DESIGN AND IMPLEMENTATION OF A QUALITY MANAGEMENT SYSTEM BASED ON THE ISO 9001: 2008 STANDARD FOR THE METAL-MECHANICAL COMPANY FÉNIX MAQUINARIAS S.A.C. IN THE AREA OF PRODUCTION \"that belongs to the mechanical metal sector and is dedicated to the production of machineries based on stainless steel for the agro-industrial food sector such as washing machines for jacks or trays, pepper mincers, artichokes, asparagus, ovens, etc .; Its main objective is the improvement of processes and obtaining economic benefits for the company. The company FÉNIX MAQUINARIAS S.A.C. has been positioning in the sector and maintaining an adequate growth due to the relationship with its customers, due to this it is necessary to have an efficient and effective organizational structure improving the execution of its processes. Also in the company there are problems that are manifested in the disorganization of the company, the difficulty in the execution of their processes, having waste of raw material, longer production times, non-standardized procedures in any of their areas. Due to this, the company has the need to design and implement a Quality Management Sys",
