    "titulo": "Diseño de un Sistema de Gestión de Calidad en base a la Norma ISO 9001:2015 para el Proceso de Almacenamiento de Productos en una Empresa de Alimentos",
    "autor": "Echevarría Ruiz, Gianpool Mariano",
    "asesor": "Rojas Naccha, Julio César",
    "anio": 2018,
    "area": "Gestión de la Calidad",
    "resumen": "El objetivo del presente trabajo fue diseñar un Sistema de Gestión de Calidad en base a la Norma ISO 9001:2015 para una empresa del sector alimentario dedicada al proceso de almacenamiento productos no perecibles, destinados principalmente a los niños de educación inicial y primaria que participan del Programa Nacional de Alimentación Escolar Qali Warma. El diseño del Sistema de Gestión de Calidad se inició con la recolección de información de la empresa, siendo parte fundamental la aplicación de la lista de verificación cuantitativa en base a la norma antes mencionada. A partir de ello, se realizó el diagnóstico de la situación actual y posteriormente se determinó los puntos deficientes que enfrenta la entidad debido a sus procesos evaluados. Finalmente se realizó la propuesta de mejora mediante la elaboración del Manual de Calidad, incluyendo la documentación obligatoria (procedimientos, programas, registros) que establece la Norma ISO 9001:2015 para la mejora y eficacia de su Sistema de Gestión de Calidad en una futura implementación.",
