    "resumen": "The present experience was carried out in the work Open Plaza Piura III expand, developed by the company Steelwork Ingenieros S.A.C. and it's about project management. This work was carried out between June and August 2015 and was won in a private tender that was developed by the client G.P.I. Falabella Peru, whose purpose was to find a company that makes metal structures in this work. This paper shows the coordination, work and contributions made as a project manager, since an industrial engineer has the necessary skills to develop in an efficient and professional manner, thanks to the fact that the industrial engineer studies operations research, and the projects are a branch of that field of study The professional work function was developed where the professional reality of the industrial engineer was discussed, the theoretical and conceptual framework that is necessary to develop this report on project management and the objectives that are to be achieved. The experience report in the professional field was developed as project manager of the Expansion Open Plaza Piura III project. The events were described from when the invitation to the private tender was achieved until the ",
