    "area": "Logística y Cadena de Suministro",
    "resumen": "The objective of the present work is to analyze and redesign the management of the logistics process for the purchase of national products and inputs in the company Técnica Avícola SA, which will serve as the basis for the improvement in the management of national purchases as well as Future modifications in the integrated system of information with which the company currently counts. The For the development of this work, meetings were held with all those involved in the process of logistics management of the purchase of national products and inputs. Then using the Business Process Management methodology, the AS-IS version of the processes was obtained, obtaining the process mapping through the BPMN (Business Process Model and Notation) notation and supported by the Bizagi Modeler software. Once the AS-IS version was obtained, the respective analysis was started, finding problems and opportunities for improvement within the process, to which solution proposals are offered. Finally, the TO-BE version of the logistics management process for the purchase of national products and inputs is generated, which indicates the changes that must be generated throughout the process, in addition",
