    "area": "Seguridad y Salud Ocupacional",
    "resumen": "The present research work entitled: the management system in safety and health at work and its effect on the productivity of the company Services General Santa Teresita EIRL, year 2016., is performed in order to determine the effect of the system of management of safety and health at work in the productivity of the General investment company Santa Teresita EIRL year 2016. The investigation allowed us to observe that the company does not have an adequate Health and Safety system which generates deficiencies such as lack of safety equipment for staff, consequential fines for surprise inspections, loss of working hours and even temporary Activities of work accidents. The implementation of an adequate management system in occupational health and safety would give the company substantial benefits, such as reduction in operating costs of production, maximization of benefits, improvement of the institutional image of third parties, and Compliance with our regulations. At the end of the present investigation it is concluded that the management of the proposed mechanisms has increased productivity in the company, and this is reflected in its financial statements obtained after the implement",
