    "area": "Seguridad y Salud Ocupacional",
    "resumen": "In the last years a good part of the activity has been realized with the support of contracting enterprises. Although the Law indicates that the workers of a contractor can not be assigned for the principal activity of the contractor, this norm is frequently vulnerable and manipulated to the favor of the Mining Enterprise. Showing the grade of the in – protectiveness of the worker who works for a contracting enterprise; the frequent accidents at work – according to the statistics published by the Ministry of Energy and Mining there have been 899 fatal accidents in the last sixteen years (2000 - 2015) of which 580 of worker working by contractor, that means that 64% of these occurrences have happened to worker who have no working relationship whatsoever with the Mining Enterprises. This indicates that the Administrator of Safety, Occupational Health and environment of the mining enterprises are not sufficient or do not concord whit the reality of the necessity of its strategic partners. Defined the scope of the system, and then make the IPERC of all activities and implement controls at the critical activities and according to our requirements define significant hazards and our objec",
