    "resumen": "The present research aims to determine the viability, at pre-feasibility level, the implementation of a ready-mix concrete line at the company ALERCOGE SAC in Pucallpa city. This study responds to the opportunity to take advantage of the good growth prospects that the construction sector expects to achieve: 5.40% (2018), 5.40% (2019), 5.40% (2020), 5.00% (2021). For that, the research covered the following main activities: Sectorial study, market study of ready-mixed concrete, technical study, legal and environmental study and economic-financial study. ALERCOGE SAC is a construction company, located in Trujillo city, with more than 15 years of experience providing construction services. Its business strategy is oriented to new markets that offer long-term profitability. Therefore, it has as an investment alternative of the creation of a subsidiary company (ALERMIX) for the production and commercialization of ready-mixed concrete in Pucallpa city. The target market for ready-mixed concrete are contractor’s companies that carry out infrastructure projects in Pucallpa city. According to the market study, the project intends to start its operations with a 12% (31,114 m3) share of total",
