    "anio": 2017,
    "area": "Gestión de Proyectos",
    "resumen": "The idea of implementing a women’s clinic in Huamachuco city emerges as an alternative solution to the high rate of maternal mortality in Peru, especially on rural zones. For this reason, this Pre-feasibility study is carried out with the main purpose of demonstrate the technical, environmental, economic and financial viability of the project. Is important to mention that the clinic implementation will take part in 3 stages: external consultory construction, emergency area construction, clinic laboratory, obstetric and hospitalization center and construction of the surgical center and Psychoprophylaxis salon ThE project starts with the market analysis, taking in count historic data from women cares in Leoncio Prado Hospital from Huamachuco. In order to facilitate this study, ratios of womens attention are used which consist in calculate how many women are treated in determinate service for every 100 births. This allows calculating the service demand to offer in the clinic from a projection of supply and demand births. In this technical study, the macro and micro localization of the clinic are analyzed. Thanks to the demand calculation in the market analysis the equipment requiremen",
