    "anio": 2017,
    "area": "Logística y Cadena de Suministro",
    "resumen": "Vitapro es una empresa dedicada a la comercialización de alimentos para acuicultura. La visión de Vitapro es ser reconocida como la referente mundial de nutrición sustentable en acuicultura. La misión de Vitapro es alimentar al mercado acuícola mundial con las mejores soluciones nutricionales. La innovación, la asesoría técnica y los altos estándares de calidad son base de la generación de valor y bienestar para desarrollo de nuestra industria. Vitapro busca orientar a sus clientes hacia la rentabilidad como base para la generación de negocios sustentables. Vitapro posee dos marcas de alimento Nicovita y Salmofood. Nicovita actualmente se especializa en 02 categorías de alimentos para acuicultura, la primera categoría es alimento para camarón (aproximadamente 95% de las ventas) y la segunda categoría es la de alimentos para peces donde tenemos productos para Trucha y Cobia. Actualmente, Vitapro comercializa sus productos en mercados establecidos en Centroamérica (Panamá, Honduras, Costa Rica, Guatemala y Nicaragua) y Sudamérica (Perú, Ecuador, Colombia y Venezuela). La Planta Vitapro Trujillo tiene una capacidad nominal para producir alimento acuícola de 540 MIL TM al año y su prod",
