    "anio": 2017,
    "area": "Gestión de Proyectos",
    "resumen": "En diferentes empresas, inclusive en diferentes áreas de una misma empresa, el nivel de importancia y tiempo dedicados a la gestión del Clima Laboral es muy variado, dependiendo fundamentalmente de la conciencia que tienen los líderes sobre el impacto que tiene el Clima Laboral en los resultados del negocio y el rendimiento de sus colaboradores, entendiendo como rendimiento, al performance y capacidad productiva de los empleados basados entre otras cosas, al grado de disposición que tengan los colaboradores, lo que se verá dificultado si no se tiene una convivencia favorable al interior de la empresa. Existen diferentes métodos para medir el Clima Laboral, principalmente a través de encuestas estandarizadas que permiten realizar comparativos con otras empresas o áreas de la misma empresa o inclusive con un mismo equipo en diferentes líneas de tiempo. Una de las métricas más reconocidas para la medición del clima organizacional es la que fue desarrollada por el Instituto Great Place to Work, que empezó, a decir de los propios representantes del instituto, como un descubrimiento inesperado en 1981, cuando un editor de Nueva York solicitó a dos periodistas que escribieran un libro ace",
