    "resumen": "In the present report the thesis was researched intervention of the implementation of the ISO norm 9001:2008 in a fishing company for the purposes of demonstrate the variation in the efficiency of productive processes, expressed as improvement in quality indicators and production performance of the products produced as fishmeal and fish oil. The research was conducted initially, applying the checklist of the ISO norm 9001:2008 as an initial diagnosis of the company, as well as determining the efficiency of the present situation expressed in indices of quality and yields, then the processes involved were identified directly with the line of business, which make up the process map, then implement and design the appropriate documentation for the system of quality management, covering the requirements of the ISO norm 9001:2008 including the quality manual, respective procedures and indicators for monitoring and control through internal audits, subsequently effected the evaluation of impact on the process efficiency in the proposed situation. Finally, it was concluded that the implementation of the ISO norm 9001:2008 increased the efficiency of productive processes in the fishing compan",
