    "resumen": "El presente estudio tuvo como objetivo principal realizar un diseño e implementar un plan de seguridad y salud en el trabajo en el departamento de trapiche en la empresa Cartavio S.A.A., mediante la elaboración de programas teniendo en cuenta los lineamientos que permiten un adecuado entendimiento de la política expresada, cumpliendo con las normas de seguridad y la responsabilidad por la función de control de riesgos. El presente trabajo es de tipo explicativo aplicativo y de diseño de investigación pre experimental con pre prueba y post prueba. Luego de una descripción general de la empresa, se procedió a realizar un diagnóstico al Sistema de Gestión de Seguridad y Salud en el Trabajo, el cual nos evidenció un bajo porcentaje en la implementación, por ende, realizamos la identificación de peligros y evaluación de los riesgos, planteándose los controles operacionales, los cuales fueron control de ingeniería, control administrativo y control de equipos de protección personal, para disminuir los riesgos importantes y moderados. Posteriormente, se establece el plan juntamente con los programas de capacitación y entrenamiento, inspecciones, señalización, plan te contingencias. Finalme",
