    "resumen": "El presente trabajo denominado: “PROPUESTA DE UN SISTEMA DE GESTION DE SEGURIDAD Y SALUD EN EL TRABAJO PARA REDUCIR LOS ACCIDENTES EN EL PROYECTO HABITACIONAL “LAS MERCEDES” DE LA EMPRESA CHIMU CONTRATISTAS GENERALES S. A. C.” se elaboró con el objetivo de mejorar el control de la seguridad y salud ocupacional en los procesos constructivos, logrando un impacto positivo en la productividad de la empresa y la reducción de riesgos laborales. Se inició realizando un diagnóstico de la situación actual de la empresa, respecto al cumplimiento de las Norma OHSAS 18001:2007, utilizando información recolectada de los escasos registros de la empresa así como entrevistas y encuestas a los colaboradores. Se identificó los peligros, evaluación riesgos y determinó controles con el fin de reducir los riesgos laborales; también se elaboró el reglamento interno de seguridad y salud en el trabajo y un plan de respuesta a emergencias. Asimismo, se propuso los procedimientos requeridos por la norma; adjuntó y elaboro todos los documentos y formatos necesarios para poder implementar un sistema de gestión de seguridad y salud ocupacional; Finalmente se realizó la evaluación económica, calculando un VAN d",
