    "anio": 2016,
    "area": "Seguridad y Salud Ocupacional",
    "resumen": "El presente trabajo plantea una propuesta y describe la metodología a seguir para implementar un sistema de gestión de seguridad y salud en el trabajo y que puede ser aplicada en empresas similares del sector metalmecánica. La implementación de un SGSST se inicia con un diagnóstico inicial de la empresa para lo cual nos basamos en la lista de verificación de lineamientos del SGSST descrita por RM 050- 2013-TR, el resultado del diagnóstico nos sirve para plantear un SGSST adecuado a las necesidades de la empresa. En el primer y segundo capítulo se presenta los fundamentos teóricos, marco conceptual y legal, luego se presenta los materiales, métodos y técnicas de recopilación para realizar un diseño especifico del proceso de implementación del SGSST, posteriormente se presenta a la empresa, definiendo su conformación y procesos principales, para poder realizar un diagnóstico situacional y planificar el proyecto de implementación, luego se elaboró el sistema de gestión de seguridad y salud en el trabajo bajo la normativa peruana, en el cual nos indica todos los pasos que debemos considerar para la implementación, en el siguiente capítulo se dan a conocer los beneficios de la implement",
