    "anio": 2016,
    "area": "Producción y Operaciones",
    "resumen": "Esta tesis tiene como objetivo mejorar la productividad en el área de producción de la empresa Agrosemillas Don Benjamín E.I.R.L, utilizando para ello el estudio de métodos de trabajo en el proceso de llenado de tolva. Inicialmente, se recopiló datos de la distribución actual de almacén; para luego desarrollar una propuesta de distribución que minimice las distancias y tiempo recorridos. El análisis del método de trabajo actual, permitió proponer una alternativa con la implementación de equipo que facilite el trabajo de los operarios y disminuya el tiempo requerido para llevar a cabo el proceso de llenado de tolva. Se realizó un estudio de tiempos con cronómetro para establecer el tiempo estándar al trabajar con la propuesta de mejora del método de trabajo; y un muestreo de trabajo en la actividad de limpieza en la última parte del proceso productivo ya que se observó que el tiempo dedicado a esta actividad está asignado sin un estudio que lo fundamente y por otro lado la propuesta desarrollada permite dedicar menos tiempo a esta actividad. Se diagramó y analizó el método propuesto para luego compararlo con el método actual y verificar su efecto en la productividad de la empresa. E",
