    "anio": 2016,
    "area": "Gestión de Proyectos",
    "resumen": "El presente trabajo de investigación titulado “Diseño e Implementación de un Cuadro de Mando Integral para mejorar la Gestión de Clientes en la Sucursal del Banco Azteca del Perú – Oficina Chepén”, es propuesta para mejorar la gestión de Clientes, con el fin de orientar y desarrollar objetivos preestablecidos, y entrelazar en forma eficiente las actividades y tareas para el logro de la misión, a las entidades financieras corresponde al crecimiento e incremento en cuanto captación de clientes, que en consecuencia generará grandes beneficios en dicha entidad. Esta investigación tiene dos etapas diferenciadas: Proyecto de Investigación y el Desarrollo de la Tesis. En la primera etapa, se busca obtener el plan de tesis donde se generaliza el trabajo a realizar y, en la segunda etapa se desarrolla el plan de trabajo, específicamente, se presenta el diseño de un Cuadro de Mando Integral para la entidad financiera Banco Azteca del Perú (BAZ). En donde, en primer lugar, se determina el problema, se plantean los objetivos y su justificación. En segundo lugar se da a conocer la base teórica y legal que sustenta el modelo de diseño en cuestión: las perspectivas que contiene el cuadro de mando",
