    "anio": 2016,
    "area": "Gestión de Proyectos",
    "resumen": "La presente investigación se denomina “DISEÑO DE UN PLAN ESTRATÉGICO PARA MEJORAR EL POSICIONAMIENTO DE LA EMPRESA DE PANIFICACIÓN INDUSTRIAL BARLETTA S.A” y, así como el título lo dice, tiene como principal objetivo mejorar el posicionamiento de la empresa BARLETTA S.A. a través del desarrollo de un plan estratégico. La iniciativa nace como una sugerencia a la Gerencia General de la empresa mencionada ante la necesidad de la misma de enfrentar la pérdida parcial de su principal cliente y así no solo estar preparados para el peor escenario sino llevar a la compañía a otro nivel de posicionamiento en el mercado. Como parte de la influencia del Balanced Score Card orientado a la estrategia, la presente tesis inició desarrollando el diagnóstico de la empresa a nivel interno y externo, continuando con la definición del direccionamiento estratégico de la empresa, (misión, visión, objetivos estratégicos y valores), lo cual permitió la identificación de Fortalezas, Debilidades, Oportunidades y Amenazas. Una vez realizado el diagnóstico estratégico, la información obtenida es analizada y procesada para redefinir los objetivos estratégicos propuestos inicialmente para los años 2016 y 2017 y",
