    "titulo": "rediseño del proceso de despacho de concreto pre-mezclado y su influencia en la productividad, en la empresa dino s.r.l. zonal trujillo",
    "autor": "Chávez Loyola, Yrvin Guillermo; Jácobo Zare, Larry Anthony",
    "asesor": "Docente Asesor — Escuela de Ing. Industrial UNT",
    "anio": 2015,
    "area": "Logística y Cadena de Suministro",
    "resumen": "En el presente proyecto de tesis, se propone un rediseño del proceso de despacho de concreto pre-mezclado para la empresa Distribuidora Norte Pacasmayo SRL. Teniendo alcance a las áreas de producción, planificación y ventas. Esta propuesta mejorará el uso de nuestros recursos y ser productivos, mediante la gestión de indicadores de productividad. El método utilizado es el deductivo, se tomó como población a las actividades del proceso de despacho que realiza la empresa, obteniendo la información con la técnica de observación y entrevista a clientes y trabajadores de la empresa. Luego se procedió a determinar el diagrama de flujo de la empresa y analizar las interacciones entre las diferentes áreas. En la etapa del análisis del proceso, se utilizaron herramientas como diagrama de Pareto y diagrama de Ishikawa. Finalmente a través de estas herramientas utilizadas, se dio la propuesta de mejora. De la propuesta, se estimó como resultado, el incremento de la productividad mediante el indicador: m3 de concreto pre-mezclado despachado por horas – hombre. El indicador se mejoró de 1,47m3/hh a 1,85 m3/hh, además que el índice de atención al cliente mejoró considerablemente, debido al traba",
