    "resumen": "El presente trabajo describe la metodología para realizar el diagnóstico y elaboración de un Plan de Seguridad en el Trabajo en una empresa de producción de azúcar, con el fin de cumplir con los estándares de Seguridad exigidos por leyes y normas peruanas; así como minimizar los riesgos y reducir la frecuencia de accidentes. El desarrollo de la tesis comienza realizando un diagnóstico de la seguridad existente en la empresa; basándonos en la Lista de Verificación de Lineamientos del Sistema de Gestión de Seguridad y Salud en el Trabajo que forma parte de la RM 050-2013-TR, dada por el Ministerio de Trabajo y Promoción del Empleo, cuyo fin es conocer el nivel de cumplimiento de los requisitos planteados en la Ley 29783 a través del DS 005-2012-TR. Luego se elaboró el IPERC de todas las actividades para poder aplicar controles a las actividades críticas de acuerdo a los peligros significativos; esto nos ayudó a definir la Política de Seguridad y elaborar el Plan de Seguridad en el Trabajo (definir objetivos, metas y programas) para evaluar su cumplimiento. El diagnóstico nos ayudó a identificar que el personal no es consciente de los peligros que los rodea y que hay un alto riesgo de",
