    "area": "Logística y Cadena de Suministro",
    "resumen": "El presente trabajo pretende ser un aporte para mejorar la eficiencia de la Gestión en el área logística de la Municipalidad Provincial de Sánchez Carrión. El trabajo consta de cinco capítulos, en los cuales se ha determinado las variables que influyen negativamente originando demora en la ejecución de las obras por administración directa, lo cual trae como consecuencia un incremento en los costos de ejecución, así como la imposibilidad de cumplir con el plazo de ejecución, perjudicando de esta manera a la población beneficiaria de los servicios que brinda la Municipalidad. Luego de haberse detectado la problemática existente en el área de Logística de la Municipalidad Provincial de Sánchez Carrión, se ha concluido en la necesidad de proponer un procedimiento ordenado de todas las etapas del abastecimiento logístico de conformidad con las normas que regulan las contrataciones del Estado, con lo cual se pretende lograr un abastecimiento oportuno de conformidad con el cronograma de ejecución de las obras por administración directa. Asímismo, el presente trabajo incorpora la problemática del abastecimiento oportuno de los alimentos para el apoyo a los programas sociales. Luego de habe",
