    "area": "Logística y Cadena de Suministro",
    "resumen": "La presente tesis tiene como objetivo determinar la influencia de la aplicación de la Mejora Continua en los Costos de Inventarios de los Procesos de Gestión de Suministros de la Compañía Operadora de Gas del Amazonas (Coga), empresa con más de siete años de operación en el país, encargada de garantizar la Operación y Mantenimiento del Sistema de Transporte de Gas Natural. La unidad de análisis de esta investigación- que es la Gestión de Suministros de Coga- esta conformada por los siguientes subprocesos: Gestión del Requerimiento, de Abastecimientos y Almacenamiento. Los mismos que fueron estudiados por el Método Deductivo y bajo un diseño Pre-Experimental. Este estudio responde a la metodología del DMAIC (definir, medir, analizar, mejorar y controlar), considerada una herramienta robusta y universal de la mejora continua. Cada etapa de esta metodología tiene un procedimiento a seguir e involucra distintas técnicas y herramientas para la recolección y procesamiento de la información. En este trabajo, se han combinado diversas técnicas, desde la observación de un proceso, las entrevistas directas, diagramaciones, análisis de datos históricos y hasta cálculos complejos. En una prime",
