    "titulo": "El control oportuno de los Costos de Producción y su incidencia en la rentabilidad de una Empresa Industrial Siderúrgica",
    "autor": "Espejo Rivera, Ivar David",
    "asesor": "Calmet Reyna, Enrique",
    "anio": 2013,
    "area": "Gestión de Proyectos",
    "resumen": "La investigación realizada sobre el control de costos ofrece una herramienta para la medición, análisis e información para la toma de decisiones que permita corregir las variaciones no deseables. Dada las circunstancias actuales, que conduce a un constante aumento de las materias primas y la creciente competencia, como consecuencia de los TLC1, obliga a implementar un riguroso control de costos aunado a programas de reducción de costos. La formulación del procedimiento del costo patrón adecuado a la industria siderúrgica, teniendo en consideración los factores determinantes del costo, como los ratio de consumo, precio de las materias primas y producción, permite obtener los costos de producción de los diferentes procesos productivos y de la comparación de estos, las variaciones que serán analizadas e informadas. Las reuniones a llevarse a cabo permitirán que la gerencia conozca rápidamente los resultados y de la comparación con las metas programadas adopte oportunamente las medidas correctivas, lógicamente luego de una amplia discusión de causa y efecto de las desviaciones con respecto a los patrones programados establecidos. Toda reducción de costo de producción incide directament",
