    "anio": 2012,
    "area": "Seguridad y Salud Ocupacional",
    "resumen": "ABSTRACT In the this work an evaluation of labor risks in the work areas of the Archaeological Complex of Sechin was realized that is located in the Region of Ancash, the applied methodology corresponded to a documentary investigation of descriptive field and to detect the different present risks in this area. The process began with the description of the present situation, and then information was obtained with respect to the types of risks, agents and consequences in order to realize the respective evaluation of risk. It was managed to determine that the risks that generate major impact were the physical, mechanics, biological, disergonomics and psycho-social. Preventive strategies framed in the proposal of an implementation of security and occupational health with the lineament’s of Norm OSHAS settled down 18001:2007, later to obtain major benefit, productivity, efficiency and security of the physical integrity of the workers of the Archaeological Complex of Sechin. Finally some corrective measures to improve the present situation of the archaeological complex until the implementation of occupational health and security system were done.",
