    "id": "usil-6aecb568-367",
    "titulo": "Implementación de un modelo de abastecimiento de repuestos críticos para la mejora de las paradas operativas en Pyramid Metals S.A.C., Miraflores, 2025",
    "autor": "Galarza Quispe, Renzo Daniel",
