    "anio": 2026,
    "area": "Logística y Cadena de Suministro",
    "resumen": "En el contexto actual del sector minero–metalúrgico, caracterizado por altos niveles de exigencia operativa, competitividad y dependencia de la disponibilidad continua de activos productivos, la gestión eficiente del abastecimiento de repuestos críticos se ha convertido en un factor estratégico para garantizar la continuidad operativa y la sostenibilidad empresarial. La indisponibilidad de repuestos esenciales genera paradas operativas no programadas, retrasos en la producción, deterioro de equipos y sobrecostos logísticos, afectando directamente la productividad, los costos operativos y la rentabilidad de las organizaciones. En este escenario, la implementación de modelos de abastecimiento estratégico, como la Matriz de Kraljic, constituye una herramienta fundamental para clasificar los repuestos según su impacto operativo y riesgo de suministro, permitiendo optimizar la gestión de inventarios, fortalecer la planificación logística y mejorar la toma de decisiones en el abastecimiento. En el caso de la empresa Pyramid Metals S.A.C., organización peruana dedicada al procesamiento y comercialización de minerales metálicos, se identificaron deficiencias en la gestión del abastecimient",
