    "titulo": "Implementación de un sistema de gestión visual mediante Business Intelligence para mejorar la productividad bajo el enfoque Lean Manufacturing en Cementos Inka, planta San Andrés, Lima, 2024",
    "autor": "Ramos Castro, Kennedy Linder",
