    "anio": 2026,
    "area": "Producción y Operaciones",
    "resumen": "En el contexto actual de la industria manufacturera caracterizado por una alta competitividad y una creciente exigencia en términos de eficiencia operativa, las empresas buscan constantemente optimizar sus procesos productivos para asegurar su sostenibilidad y rentabilidad. En este escenario, el control y monitoreo de los indicadores de desempeño, como el OEE se han convertido en elementos clave para evaluar el nivel de productividad. Asimismo la adopción de herramientas Lean Manufacturing y el uso de tecnologías de información como Business Intelligence, permiten mejorar la visibilidad de los procesos y facilitar la toma de decisiones en tiempo real. En el caso de Cementos Inka planta San Andrés ubicada se identificaron deficiencias importantes en el desempeño de la producción, reflejadas en un bajo nivel del indicador OEE, el cual presentaba un promedio aproximado de 41%, debido principalmente a la presencia de paradas no planificadas, fallas recurrentes en equipos críticos como el molino, elevadores y sistemas de dosificación, así como a la falta de estandarización en las actividades operativas y a un manejo ineficiente de la información productiva. Además el uso de registros ma",
