    "anio": 2026,
    "area": "Logística y Cadena de Suministro",
    "resumen": "La presente investigación tuvo como objetivo determinar de qué manera la mejora en la gestión logística incrementa la productividad en una empresa de construcción, Lima 2024. La intervención comprendió la clasificación ABC y la estandarización de procedimientos, instructivos y formatos de control orientados a la clasificación de inventarios, la selección de proveedores, la capacitación del personal y la correcta ejecución del sistema Justo a Tiempo (JIT). El estudio fue de tipo aplicado, con enfoque cuantitativo, nivel explicativo y diseño pre-experimental, bajo un esquema pre-test – intervención – post-test (O1–X–O2). La unidad de análisis estuvo conformada por 30 reportes técnicos, con fichas de registro como instrumento. Tras la implementación, la precisión en la clasificación de inventarios aumentó de 65.23 % a 82.23 %; el cumplimiento en la selección de proveedores pasó de 62.60 % a 78.33 %; la cobertura de capacitación del personal en JIT se incrementó de 62.23 % a 84.03 %; y la correcta ejecución del JIT pasó de 63.47 % a 81.20 %. En la variable dependiente, el índice de productividad se incrementó de 67.97 % en el pre-test a 83.70 % en el post-test, diferencia estadísticame",
    "palabrasClave": [
      "Gestión logística",
      "Productividad",
      "Proveedores"
    ],
