    "anio": 2025,
    "area": "Seguridad y Salud Ocupacional",
    "resumen": "El presente trabajo tuvo por objetivo generar un ambiente más seguro y comprometido con la seguridad y salud ocupacional mediante la implantación de un sistema de gestión de Seguridad y Salud en el Trabajo bajo los lineamientos de la norma ISO 45001:2018, por lo que inicialmente se realizó un diagnóstico situacional, con los resultados obtenidos, se procedió a implementar la documentación que cumpla con los criterios de la norma ISO 45001:2018, en cada uno de los procesos determinados, logrando de esta manera un mejor manejo organizacional con respecto a seguridad y salud ocupacional, teniendo en cuanta la importancia de que el sistema nos permite alinear objetivos enfocados en SST, a la organización para cumplir metas en el desarrollo de sus actividades. Como resultado del presente sistema implementado se logró realizar, la validación mediante una auditoría interna y una auditoría externa como proceso de certificación. Se concluye el presente trabajo, que con la implementación completa del sistema de gestión bajo los lineamientos de la ISO 45001:2018 se logró cumplir con el objetivo ya que se logró implementar todos los controles necesarios en materia de SST, así como la concienti",
