    "area": "Logística y Cadena de Suministro",
    "resumen": "El presente trabajo de investigación tiene como objetivo diseñar una base de datos que permita la gestión eficiente de órdenes de compra, cotizaciones, facturas, notas de crédito y guías de remisión en una empresa del sector médico dedicada a la importación y distribución de reactivos de control de calidad. Actualmente, la empresa enfrenta dificultades en el seguimiento de las órdenes de compra, lo que genera demoras en la entrega de productos y dificultades en la conciliación de documentos comerciales. Para solucionar esta problemática, se propone un modelo de base de datos relacional que centralice la información y optimice el flujo de datos entre las distintas áreas de la empresa. La metodología utilizada incluye el análisis de requerimientos, la normalización de datos y la implementación de consultas SQL para la obtención de reportes clave. Los resultados esperados incluyen la reducción de tiempos en la gestión de documentos, la mejora en el control de inventarios y una mayor trazabilidad de las transacciones comerciales. Asimismo, se busca proporcionar a la empresa una herramienta que facilite la toma de decisiones basada en datos precisos y actualizados. En conclusión, la imp",
