    "titulo": "Aplicación de la Programación lineal para mejorar la red de abastecimiento del gas natural licuado en vehículos pesados de largo recorrido en la costa peruana",
    "autor": "Vega Torres, Rosa María",
    "asesor": "Canelo Sotelo, César Aldo",
    "anio": 2025,
    "area": "Logística y Cadena de Suministro",
    "resumen": "El presente trabajo de investigación analiza la optimización de la red de abastecimiento de gas natural licuado (GNL) para los vehículos pesados de largo recorrido en la costa peruana, a través de la técnica de la programación lineal (PL), para optimizar la eficiencia en el uso de los componentes de la red de abastecimiento, así como, la reducción en los costos de inversión. El estudio se focaliza en determinar puntos críticos de la actual red de abastecimiento, la cual se encuentra en un lento proceso de desarrollo, a fin de proponer una alternativa de solución que optimice los recursos. El análisis incluye la determinación de los puntos de ubicación de las estaciones de servicio de GNL, la capacidad de almacenamiento en cada estación de servicio, la proyección de la demanda GNL para un horizonte de diez años y la cantidad de componentes a utilizar (tractos, cisternas criogénicas y tanques de almacenamiento de GNL), con la finalidad de asegurar la continuidad el abastecimiento de GNL, haciendo uso eficiente de los recursos. Además, se realiza un análisis exhaustivo del subsidio del diésel para estimar un escenario futuro, en caso se persista por el diésel como única alternativa de",
