    "resumen": "La presente tesis aboca una problemática sobre las dificultades con las que cuenta una empresa de bebidas no alcohólicas en su proceso de distribución a clientes en la zona del Mercado N° 1 de Puente Piedra, puesto que le generan que su tiempo en el mercado sea por encima de la meta. La investigación inicia justificando la necesidad de utilizar las metodologías y herramientas para mejorar la calidad de las compañías, puesto que con ellas se logra visualizar las causas raíces de los problemas para poder analizarlas y lograr plantear posibles soluciones. Luego de haber realizado dichos análisis, el estudio plantea implementar un almacén auxiliar que delimite un lugar fijo desde donde se pueda realizar la distribución y así se oxigene a los ayudantes de reparto y puedan disminuir sus tiempos improductivos que tenían por el hecho de continuar con un proceso que cada vez se hacía más complejo debido a las particularidades de la zona de distribución. Posteriormente se realiza un análisis de tiempos descomponiendo los procesos actuales y se propone nuevos procesos que mejoren el uso de los recursos logrando hacer la distribución más eficiente, con dicho análisis se logra plantear el incre",
