    "asesor": "Azalgara Neira, Pablo Alfonso",
    "anio": 2021,
    "area": "Logística y Cadena de Suministro",
    "resumen": "El presente trabajo de investigación tiene por finalidad proponer un sistema de abastecimiento que permita optimizar la gestión logística de la empresa FAGOMA S.A.C., en primer lugar se realizó el diagnóstico de la situación actual del sistema de abastecimiento de la empresa, después se identificó los principales problemas que se deben mejorar, luego se desarrolló la propuesta de mejora en cada etapa del sistema de abastecimiento y para concluir se determinó el costo / beneficio de la propuesta. Esta investigación es de tipo cuantitativa y cualitativa; de diseño no experimental y como metodología se utilizaron técnicas como la entrevista, observación de campo y levantamiento de datos a nivel de documentos, obteniendo datos con lo que se pudo determinar que la empresa carece de un adecuado sistema de abastecimiento al momento de adquirir sus materiales. Para un mayor desarrollo de la gestión logística se plantean mejoras en los procesos de abastecimiento, almacenamiento e inventarios. Finalmente, se evaluó el costo / beneficio de la propuesta, obteniéndose 1.49, lo que explica que por cada sol invertido habrá un beneficio para la empresa de 0.49 soles.",
