    "anio": 2020,
    "area": "Producción y Operaciones",
    "resumen": "Se realizó un trabajo de investigación en la empresa Carlei Telecomunicaciones S.A.C. diagnosticando su problemática en el área de operaciones con el propósito de desarrollar una propuesta de mejora utilizando herramientas y metodologías de ingeniería industrial, con el supuesto de que la correcta aplicación de estas incrementara la rentabilidad de la empresa. Para estudiar la problemática se realizó un estudio de carácter exploratoria y descriptiva; la información se obtuvo mediante la observación, el registro de datos históricos, la consulta, la entrevista y a través de encuestas. Esta información fue organizada en un Diagramas de Ishikawa, Diagrama de Pareto y Matriz de Priorización. Con estas herramientas se determinó que el 83% de los problemas de la empresa están generados por la alta variación de tiempo en los procesos de instalación, el personal técnico de instalación desconoce el proceso de RF, falta de materiales y por las continuas averías en los vehículos. Se determinó mediante un análisis de costos que la perdida de la empresa es de S/. 131 182.10 lo que afecta directamente a la rentabilidad de la empresa. Con la aplicación de las herramientas de mejora se logró obtene",
