    "resumen": "The general objective of this improvement proposal is to incrementar el índice de productividad of the company Fábrica de Alambres y Clavos Myl S.A.C. and for this it has six chapters which will be described below. In chapter I, we present a brief historical review of Myl S.A.C. We refer to the products they offer, the types of customers they have and the definition of the hipótesis del proyecto. In chapter II, the external and internal environment of the company was analyzed, thus determining the PEST matrix and the five forces of Porter in order to identify the opportunities and weaknesses that it possesses. In Chapter III, the flow of transformation of the raw material until it is finished product will be known in detail (trefilado, producción de clavos, pulido y encajado), what indicators the company uses to measure its productivity and the identification of the root cause of the problem of low productivity thanks to the use of diagrama Ishikawa. In chapter IV and V, with the use of Diagrama de Pareto, the main root causes will be identified to propose alternative solutions that, with engineering methods, will be selected the most profitable and will proceed to develop the engi",
