    "titulo": "Diseño e implementación de un sistema de control logístico para optimizar la gestión operativa de un centro de distribución de telas",
    "autor": "Roca Rivas, Carlos Gabriel",
    "asesor": "Ruiz Lizama, Edgar Cruz",
    "anio": 2019,
    "area": "Logística y Cadena de Suministro",
    "resumen": "Optimiza la gestión operativa del Centro de Distribución (CEDIS) de una empresa comercializadora de telas de la industria textil por medio del diseño e implementación de un sistema de control de logístico. El impacto esperado es la mejora del ingreso de órdenes de importación dentro de las 24 horas en el stock disponible del sistema, la gestión del stock para asegurar el paralelismo lógico-físico del inventario, y el nivel de atención de los pedidos entregados a tiempo para el cliente. El presente estudio corresponde a una investigación de tipo aplicada, con un enfoque cuantitativo, longitudinal y analítico. Las variables que se relacionan son sistema de control de logístico y la gestión operativa. El procesamiento de datos permitió determinar que la gestión operativa del CEDIS, por medio de las dimensiones definidas tales como el control de los ingresos, control de inventarios, y control de despachos, logró una mejora considerable producto del diseño e implementación de un sistema de control logístico. Los cambios entre el año base (año anterior a la implementación) y el año de la implementación fueron el incremento en 13% del % de órdenes ingresadas a tiempo en el stock disponibl",
