    "resumen": "La presente investigación fue desarrollada en la empresa de calzado CARYERI SHOES E.I.R.L. Esta no cuenta con ninguna metodología ni herramientas necesarias para el desarrollo de su productividad; es por ello que al evaluar cada una de sus causas raíces encontramos los siguientes sobrecostos; en el área de producción por falta de mano de obra incurre en S/. 27,432.00, por falta de un sistema de capacitación al personal en S/. 6,279.84, por mala distribución de planta en S/. 648.00, no cuentan con un sistema de control logística S/. 203,549.94 y por estaciones desordenadas y sucias en S/. 11,685.98; en el área de logística por control de inventarios S/. 3,646.50; por formatos de control de procesos logísticos S/. 3,247.80; por un programa de mantenimiento S/. 332.64; por aprovechamiento del área de almacén S/. 3,032.84. Teniendo un costo total en el área de producción de S/. 249,595.76 y en el área de logística de S/. 10,259.78. Por todo lo expuesto, a continuación, para el área de producción se utiliza una metodología de trabajo utilizando las herramientas de Ingeniería; MRP para combatir los excesos de mermas, elevados costos de inventarios en un 100%, las 5S para disminuir las es",
