    "anio": 2019,
    "area": "Logística y Cadena de Suministro",
    "resumen": "El presente trabajo tiene como objetivo general el desarrollo de una propuesta de mejora para las áreas de Logística y Mantenimiento en el servicio de pesaje para reducir los costos operativos en la empresa BALANZAS UNIVERSAL S.A.C. Para ello se realizó un diagrama de Ishikawa identificando los problemas que causan dichas pérdidas y también un diagrama de Pareto otorgando una priorización de ellas en la empresa. Luego, en un cuadro de matrices de indicadores o causa-raíz pondremos a manera de resumen las causas de pérdidas, y cómo medirlas. También analizaremos los valores actuales y valores meta de tal manera que las herramientas de mejora a utilizar nos ayuden a evitar pérdidas económicas elevadas. Mediante las metodologías estudiadas a lo largo de nuestra carrera de Ingeniería Industrial, tales como: Gestión de Mantenimiento, Gestión por Procesos, Lean Manufacturing, Gestión de Personas y Gestión de Proveedores analizaremos el presente proyecto de tesis a mejorar. Posteriormente se realizó un análisis económico financiero para comprobar si el estudio realizado es viable, puesto que se obtuvo un VAN de S/ 1,344.98 soles, TIR de 21.76% y un B/C de 1.86. Concluyendo que esta propue",
