    "area": "Producción y Operaciones",
    "resumen": "En la actualidad de ha desarrollado diversidad de procesos de producción para una mejora continua en las diferentes industrias manufactures, mineras desde ya mucho atrás para el beneficio del hombre y su progreso del mismo, pero a lo largo de esta trayectoria de mejoora continua se ha dejado de lado la seguridad, concerniente al desarrollo de buenas estrategias y/o procesos de prevención y riesgos, es por ello que se busca reimplantar un sistema de prevención en las distintas áreas en las empresas de mantenimiento de maquinaria con el fin de minimizar riesgos y actos sub-estándares, basados en documentos e investigaciones sobre procesos de mantenimiento preventivo en empresas, talleres e industrias las cuales nos podrá determinar un análisis más completo sobre la situación en las empresas, dichos documentos fueron elegidos por contextualizar las medidas de prevención en empresas, las cuales actualmente han dejado de lado procesos de mantenimiento por la gran competitividad que se ha generado a través de la industrialización. En el medio actual del bum minero las empresas optan por la producción y no calidad de proceso obviando la prevención de riesgos del personal y la maquinaria, ",
