    "resumen": "Implementa un plan de gestión que permite mejorar la administración de la materia prima en el área de producción de la empresa METROCOMUNICACIONES SAC. Para las mejoras en la gestión de la materia prima se implementa planes de control, así como en el tiempo de cierre del registro de consumos de cada trabajo, el error del registro de materia prima con varias marcas y la reducción de las devoluciones por el error en las transferencias realizadas. Esto se logra eliminando aquellos materiales que cuentan con una variedad de marcas, registrando a tiempo el consumo de los materiales para cada orden de trabajo verificando las OT, esto apoya a minimizar los errores de las transferencias realizadas por el almacén para así evitar las devoluciones, siempre con la capacitación continua del operario. Se utilizan las entrevistas con los usuarios para la solicitud de la información necesaria así como la observación experimental del área de producción y almacén. La información obtenida se ingresa al software estadístico MINITAB para su evaluación y análisis respectivo mediante el planteamiento de hipótesis con un nivel de confianza del 95%. Como resultados finales se afirma lo siguiente: se demues",
